import {createLifeCommerceUI} from './life-commerce-ui.js?v=49';
import {UPGRADE_GATES,reputationName,canGrow,hasBulkHarvest} from './life-progression.js?v=49';
import {CROPS,HOME_LEVELS,DECOR,DECOR_SLOTS,activePlots,plotState,atHome,plantCrop,harvestCrop,buyLife,buyLumber,upgradeHome,openPaddy,placeDecor,craftDecor,setLifeLevel,freshLife,grantLifeStarter} from './homestead.js?v=49';
import {ANCIENT_COUNTRIES} from './regions/ancient.js?v=49';
export function createHomesteadUI(api){
  const {$,panel,imageTag,toast,save,hud,travel,esc}=api,s=()=>api.state(),home=()=>s().ancient.home;
  const commerce=createLifeCommerceUI({...api,openFarm:()=>farm(),resetLife:()=>Object.assign(home(),freshLife()),grantStarter:()=>grantLifeStarter(s())});
  const time=ms=>{const n=Math.ceil(ms/1000);return Math.floor(n/60)+'분 '+String(n%60).padStart(2,'0')+'초';};
  const art=(id,alt,cls='')=>imageTag(id,alt,cls);
  const slots=()=>DECOR_SLOTS.slice(0,HOME_LEVELS[home().level].slots);
  const nav=page=>`<nav class="life-tabs" aria-label="거처 관리">${[['farm','밭·논'],['market','씨앗·생활'],['growth','집 키우기'],['decor','꾸미기'],['orders','마을 부탁']].map(([id,name])=>`<button data-life-tab="${id}" ${page===id?'aria-current="page" class="selected"':''}>${name}</button>`).join('')}</nav>`;
  function heading(){const h=home(),c=ANCIENT_COUNTRIES[s().ancient.country];return `<div class="life-heading">${art('life-home-'+s().ancient.country+'-'+h.level,c.name+'의 '+h.level+'단계 거처')}<div><small>${c.name} · 나의 생활 공간</small><h3>${esc(s().nickname)}의 거처 <span>${h.level}단계</span></h3><p>${HOME_LEVELS[h.level].name} · ${reputationName(h.reputation)} <b>${h.reputation}/100</b></p><p class="life-wallet">${s().coins.toLocaleString()} 엽전</p></div></div>`;}
  function show(page,body){
    if(!atHome(s())){toast('집 안이나 내 마당의 생활 책상에서 관리하자.');return;}
    panel('내 거처',heading()+nav(page)+`<div class="life-content">${body}</div><div class="life-footer"><button id="life-space">${s().map.includes('-yard-')?'집 안으로':'내 마당으로'}</button><button id="life-village">마을로 나가기</button></div>`,{wide:true,type:'homestead'});
    document.querySelectorAll('[data-life-tab]').forEach(b=>b.onclick=()=>open(b.dataset.lifeTab));
    $('#life-space').onclick=()=>{travel(s().map.includes('-yard-')?ANCIENT_COUNTRIES[s().ancient.country].home:'ancient-yard-'+s().ancient.country);if(s().map===ANCIENT_COUNTRIES[s().ancient.country].home)api.finishEvent('ancient:home');};
    $('#life-village').onclick=()=>travel(ANCIENT_COUNTRIES[s().ancient.country].village);
  }
  function commit(message){save();hud();if(message)toast(message);}
  function clock(update){update();const timer=setInterval(update,500);api.setCleanup(()=>clearInterval(timer));}
  function farm(){
    const h=home(),plots=activePlots(h);
    show('farm',`<div class="life-section-line"><div><h3>심고, 다녀와서 수확하자.</h3><p>밭 ${h.fields}칸 · 논 ${h.paddies}칸 · 한 번 수확하면 작물 4개</p></div>${h.commerce.tools.seedBag?'<button id="life-batch">여러 칸 심기</button>':''}<button id="life-harvest-all" ${hasBulkHarvest(s())?'':'disabled'}>${hasBulkHarvest(s())?'모두 수확':'낫을 마련하면 모두 수확'}</button></div><div class="life-plots">${plots.map(p=>`<button class="life-plot" data-life-plot="${p.id}" aria-label="${p.id.startsWith('paddy')?'논':'밭'} ${p.id.split('-')[1]}">${art('life-empty-'+p.id.split('-')[0],'재배칸')}<b>${p.id.startsWith('paddy')?'논':'밭'} ${p.id.split('-')[1]}</b><span class="life-plot-name"></span><small class="life-plot-time"></small><span class="life-progress"><i></i></span></button>`).join('')}</div>${!h.paddies?`<p class="life-tip">${h.level<3?'논은 거처 3단계부터 만들 수 있어.':'집 키우기에서 논을 열면 벼를 심을 수 있어.'}</p>`:''}<p class="note">자라는 동안 낚시나 탐험을 다녀와도 좋아. 게임을 껐다 켜도 자란 시간은 이어져.</p>`);
    const update=()=>{let ready=0;for(const p of activePlots(home())){
      const b=document.querySelector(`[data-life-plot="${p.id}"]`);if(!b)continue;
      const t=plotState(p),c=CROPS[p.crop],label=p.id.startsWith('paddy')?'논':'밭';
      b.classList.toggle('ready',t.status==='ready');b.querySelector('.life-plot-name').textContent=c?.name||'비어 있음';
      b.querySelector('.life-plot-time').textContent=t.status==='empty'?'씨앗 선택하기':t.status==='ready'?'수확하기 ✓':'자라는 중 · '+time(t.remaining);
      b.querySelector('.life-progress i').style.width=t.progress*100+'%';
      const key=c?'life-'+(t.status==='ready'?'ripe':'growing')+'-'+p.crop:'life-empty-'+p.id.split('-')[0];
      if(b.dataset.art!==key){b.querySelector('img').src=api.asset(key);b.dataset.art=key;}
      b.setAttribute('aria-label',label+' '+p.id.split('-')[1]+' · '+(c?.name||'비어 있음')+' · '+b.querySelector('.life-plot-time').textContent);if(t.status==='ready')ready++;
    }const all=$('#life-harvest-all');if(all)all.disabled=!ready||!hasBulkHarvest(s());};
    document.querySelectorAll('[data-life-plot]').forEach(b=>b.onclick=()=>plot(b.dataset.lifePlot));
    if($('#life-batch'))$('#life-batch').onclick=commerce.batch;
    $('#life-harvest-all').onclick=()=>{if(!hasBulkHarvest(s()))return;let count=0;for(const p of activePlots(home()))count+=harvestCrop(s(),p.id)?.count||0;if(count)commit('작물 '+count+'개를 가방에 담았다.');farm();};clock(update);
  }
  function plot(id){
    const p=activePlots(home()).find(p=>p.id===id);if(!p)return;
    if(plotState(p).status==='ready'){const result=harvestCrop(s(),id);if(result){commit(CROPS[result.id].name+' '+result.count+'개 수확!');farm();}else toast('가방에 더 담을 자리가 없다.');return;}
    if(p.crop){const c=CROPS[p.crop];show('farm',`<div class="life-growing-detail">${art('life-growing-'+p.crop,c.name)}<h3 id="life-growing-title">${c.name}가 자라고 있어.</h3><p id="life-remaining"></p><button id="life-pick" class="primary full" disabled>자라는 중</button><button id="life-farm-back" class="full">다른 밭 보기</button></div>`);
      $('#life-farm-back').onclick=farm;$('#life-pick').onclick=()=>plot(id);clock(()=>{const t=plotState(p);$('#life-growing-title').textContent=c.name+(t.status==='ready'?'가 다 자랐다!':'가 자라고 있어.');const picture=$('.life-growing-detail img');if(picture.dataset.status!==t.status){picture.src=api.asset('life-'+(t.status==='ready'?'ripe':'growing')+'-'+p.crop);picture.dataset.status=t.status;}$('#life-remaining').textContent=t.status==='ready'?'다 자랐다. 수확할 수 있어!':time(t.remaining)+' 뒤 수확';$('#life-pick').disabled=t.status!=='ready';$('#life-pick').textContent=t.status==='ready'?'수확하기':'자라는 중';});return;}
    const kind=id.split('-')[0];show('farm',`<h3>${kind==='paddy'?'논':'밭'} ${id.split('-')[1]} · 무엇을 심을까?</h3><div class="life-shop-grid">${Object.entries(CROPS).filter(([,c])=>c.kind===kind).map(([key,c])=>`<article>${art('life-seed-'+key,c.name+' 씨앗')}<div><b>${c.name} 씨앗</b><p>${c.minutes}분 · 수확 ${c.yield}개</p><small>보유 ${home().seeds[key]}개 · 판매 개당 ${c.sale}엽전</small></div><button data-life-plant="${key}" ${home().seeds[key]?'':'disabled'}>심기</button></article>`).join('')}</div><p class="note">씨앗 1개로 한 칸에 심어. 비어 있는 칸에만 심을 수 있어.</p><button id="life-seed-shop" class="full">씨앗 사러 가기</button>`);
    document.querySelectorAll('[data-life-plant]').forEach(b=>b.onclick=()=>{if(!plantCrop(s(),id,b.dataset.lifePlant))return;commit(CROPS[b.dataset.lifePlant].name+'를 심었다.');farm();});$('#life-seed-shop').onclick=market;
  }
  function market(){const h=home();
    show('market',`${commerce.toolCards()}<h3>씨앗 · 생활 재료</h3><div class="life-shop-grid">${Object.entries(CROPS).map(([id,c])=>`<article>${art('life-seed-'+id,c.name+' 씨앗')}<div><b>${c.name} 씨앗</b><p>${c.minutes}분 · 수확 4개</p><small>${c.seed}엽전 · 보유 ${h.seeds[id]}개${c.kind==='paddy'?' · 논 전용':''}</small></div><button data-life-buy-seed="${id}" ${s().coins<c.seed||(c.kind==='paddy'&&!h.paddies)?'disabled':''}>${c.kind==='paddy'&&!h.paddies?'논 필요':'1개 구매'}</button></article>`).join('')}<article>${art('life-lumber','목재')}<div><b>목재</b><p>집 확장 · 꾸미기 제작</p><small>8엽전 · 가방 ${s().inventory.lumber||0}개</small></div><button id="life-buy-lumber" ${s().coins<8?'disabled':''}>1개 구매</button></article></div><div class="life-workshop"><h3>작업대 ${h.level<2?'· 2단계에서 열림':''}</h3><p>목재로 작은 살림을 만든다.</p><div class="row">${['woodBox','lowTable'].map(id=>`<button data-life-craft="${id}" ${h.level<2||(s().inventory.lumber||0)<DECOR[id].lumber?'disabled':''}>${DECOR[id].name} 만들기 · 목재 ${DECOR[id].lumber}개</button>`).join('')}</div></div><div class="life-sale"><h3>수확한 작물 팔기</h3><p>가방에 담은 수확물을 기존 판매 기능으로 판다.</p><div class="life-sale-grid">${Object.entries(CROPS).map(([id,c])=>`<button data-life-sell="${c.item}" ${(s().inventory[c.item]||0)>0?'':'disabled'}>${c.name} ${s().inventory[c.item]||0}개 · 개당 ${c.sale}엽전</button>`).join('')}</div><button id="life-sell-other" class="full">물고기·사냥 재료도 판매하기</button></div>`);
    commerce.bindTools(market);
    document.querySelectorAll('[data-life-buy-seed]').forEach(b=>b.onclick=()=>{if(buyLife(s(),'seed',b.dataset.lifeBuySeed))commit('씨앗 1개를 샀다.');market();});
    $('#life-buy-lumber').onclick=()=>{if(buyLumber(s()))commit('목재 1개를 샀다.');market();};
    document.querySelectorAll('[data-life-craft]').forEach(b=>b.onclick=()=>{if(craftDecor(s(),b.dataset.lifeCraft))commit(DECOR[b.dataset.lifeCraft].name+'을 만들었다.');market();});
    document.querySelectorAll('[data-life-sell]').forEach(b=>b.onclick=()=>{const id=b.dataset.lifeSell,c=Object.values(CROPS).find(c=>c.item===id);show('market',`<h3>${c.name} 판매</h3><p>보유 ${s().inventory[id]}개 · 개당 ${c.sale}엽전</p><div class="row"><button id="life-sell-one">1개 판매</button><button id="life-sell-all" class="primary">모두 판매</button></div>`);for(const [selector,n]of [['#life-sell-one',1],['#life-sell-all',s().inventory[id]]])$(selector).onclick=()=>{const amount=api.sell(id,n);if(amount)commit(amount+'엽전을 받았다.');market();};});
    $('#life-sell-other').onclick=api.selling;
  }
  function growth(){const h=home(),next=HOME_LEVELS[h.level+1],available=next&&canGrow(s())&&s().coins>=next.coins&&(s().inventory.lumber||0)>=next.lumber;
    show('growth',`<div class="life-upgrade-summary"><h3>${next?'다음 목표 · '+(h.level+1)+'단계':'넉넉한 거처가 되었다.'}</h3>${next?`<p>${next.fields}칸의 밭 · ${next.room[0]}×${next.room[1]} 집 안 · 꾸미기 ${next.slots}자리</p><p>필요: <b>${next.coins}엽전 · 목재 ${next.lumber}개</b><br>보유: ${s().coins}엽전 · 목재 ${s().inventory.lumber||0}개</p><ul class="life-goals"><li>엽전 ${s().coins} / ${next.coins}</li><li>목재 ${s().inventory.lumber||0} / ${next.lumber}</li><li>평판 ${h.reputation} / ${UPGRADE_GATES[h.level+1].reputation}</li><li>마을 부탁 ${h.commerce.completed} / ${UPGRADE_GATES[h.level+1].requests}회</li>${h.level===1?`<li>첫 수확 ${Object.values(h.harvested).some(n=>n>0)?'완료 ✓':'아직'}</li>`:''}</ul><button id="life-upgrade" class="primary full" ${available?'':'disabled'}>거처 키우기</button>`:'<p>밭과 논, 살림을 계속 가꾸어 보자.</p>'}</div><div class="life-level-grid">${Object.entries(HOME_LEVELS).map(([n,d])=>`<article class="${Number(n)===h.level?'current':''}"><div class="life-house-stage">${art('life-home-'+s().ancient.country+'-'+n,n+'단계 집')}</div><b>${n}단계 · ${d.name}</b><p>밭 ${d.fields}칸${d.paddies?' · 논 최대 '+d.paddies+'칸':''}<br>꾸미기 ${d.slots}자리</p><small>${Number(n)<h.level?'키움 ✓':Number(n)===h.level?'지금 내 거처':n==='2'?'작업대 추가':n==='3'?'논 · 수레 자리 추가':n==='4'?'넉넉한 작업·전시 공간':'농사 시작'}</small></article>`).join('')}</div><div class="life-paddy-unlock"><h3>논 만들기</h3><p>${h.level<3?'3단계부터 논을 열어 벼를 심을 수 있어.':'열린 논 '+h.paddies+' / '+HOME_LEVELS[h.level].paddies+'칸 · 다음 논 '+(h.paddies?45:30)+'엽전'}</p><button id="life-open-paddy" ${h.paddies>=HOME_LEVELS[h.level].paddies||s().coins<(h.paddies?45:30)?'disabled':''}>논 한 칸 열기</button></div><p class="note">집을 키워도 심은 작물과 보관품, 꾸미기는 남아. 세기가 바뀌어도 내 생활 공간은 이어져.</p>`);
    if(next)$('#life-upgrade').onclick=()=>{show('growth',`<h3>${h.level+1}단계로 키울까?</h3><p>${next.coins}엽전과 목재 ${next.lumber}개를 쓴다.<br>밭은 ${next.fields}칸이 되고 집과 마당이 넓어진다.</p><div class="row"><button id="life-upgrade-cancel">나중에</button><button id="life-upgrade-confirm" class="primary">집 키우기</button></div>`);$('#life-upgrade-cancel').onclick=growth;$('#life-upgrade-confirm').onclick=()=>{if(upgradeHome(s())){api.refreshWorld();commit('거처가 '+h.level+'단계로 자랐다!');}growth();};};
    $('#life-open-paddy').onclick=()=>{if(openPaddy(s()))commit('논 한 칸을 열었다. 벼 씨앗을 심어 보자.');growth();};
  }
  function decor(){const h=home();show('decor',`<h3>내 살림 놓기</h3><p>자리를 고르면 놓거나 바꿀 수 있어. 치운 물건은 다시 사용할 수 있어.</p><div class="life-decor-slots">${slots().map(slot=>`<button data-life-slot="${slot.id}">${h.placements[slot.id]?art(DECOR[h.placements[slot.id]].art,DECOR[h.placements[slot.id]].name):'<span class="life-empty-slot">＋</span>'}<b>${slot.area==='room'?'집 안':'마당'} · ${slot.name}</b><small>${h.placements[slot.id]?DECOR[h.placements[slot.id]].name:'비어 있음'}</small></button>`).join('')}</div><h3>꾸미기 물품</h3><div class="life-shop-grid">${Object.entries(DECOR).map(([id,d])=>`<article>${art(d.art,d.name)}<div><b>${d.name}</b><p>${d.area==='both'?'집 안·마당':d.area==='room'?'집 안':'마당'}</p><small>${d.price}엽전 · 보유 ${h.decorations[id]}개${d.reputation?' · 평판 '+d.reputation+' 필요':''}</small></div><button data-life-buy-decor="${id}" ${s().coins<d.price||h.reputation<(d.reputation||0)?'disabled':''}>구매</button></article>`).join('')}</div>`);
    document.querySelectorAll('[data-life-buy-decor]').forEach(b=>b.onclick=()=>{if(buyLife(s(),'decor',b.dataset.lifeBuyDecor))commit(DECOR[b.dataset.lifeBuyDecor].name+' 구매 완료.');decor();});
    document.querySelectorAll('[data-life-slot]').forEach(b=>b.onclick=()=>decorateSlot(b.dataset.lifeSlot));
  }
  function decorateSlot(id){const slot=slots().find(v=>v.id===id),h=home();if(!slot)return;const held=Object.entries(DECOR).filter(([key,d])=>(d.area==='both'||d.area===slot.area)&&(!d.wall||slot.wall)&&h.decorations[key]);
    show('decor',`<h3>${slot.name} · 무엇을 놓을까?</h3><div class="life-shop-grid">${held.map(([key,d])=>{const used=Object.values(h.placements).filter(v=>v===key).length;return `<article>${art(d.art,d.name)}<div><b>${d.name}</b><small>보유 ${h.decorations[key]} · 배치 ${used}</small></div><button data-life-place="${key}" ${h.decorations[key]<=used&&h.placements[id]!==key?'disabled':''}>놓기</button></article>`;}).join('')||'<p>이 자리에 놓을 물품이 아직 없다. 꾸미기에서 살림을 모아 보자.</p>'}</div><div class="row"><button id="life-decor-back">다른 자리 보기</button><button id="life-remove" ${h.placements[id]?'':'disabled'}>이 자리 비우기</button></div>`);
    document.querySelectorAll('[data-life-place]').forEach(b=>b.onclick=()=>{if(placeDecor(s(),id,b.dataset.lifePlace))commit('살림을 놓았다.');decor();});$('#life-remove').onclick=()=>{if(placeDecor(s(),id,null))commit('살림을 보관했다.');decor();};$('#life-decor-back').onclick=decor;
  }
  function open(page='farm'){if(!atHome(s())){toast('집 안이나 내 마당의 생활 책상에서 관리하자.');return;}({farm,market,growth,decor,orders:commerce.board}[page]||farm)();}
  function adminPanel(){
    if(!api.admin())return;const h=home();panel('거처·농사 시험',`<p class="note">기존 관리자 시험 세션 · 학생 원본에는 반영되지 않는다.</p><div class="admin-section"><h3>나라 선택 직후</h3><button id="life-qa-choice">나라 선택 직전으로</button>${Object.entries(ANCIENT_COUNTRIES).map(([id,c])=>`<button data-life-qa-country="${id}">${c.name} 정착 직후</button>`).join('')}</div><div class="admin-section"><h3>거처 단계 · 해금</h3>${[1,2,3,4].map(n=>`<button data-life-qa-level="${n}">${n}단계</button>`).join('')}<label>밭 칸 수<select id="life-qa-fields">${[2,3,4,5,6,7,8].map(n=>`<option ${n===h.fields?'selected':''}>${n}</option>`).join('')}</select></label><label>논 칸 수<select id="life-qa-paddies">${[0,1,2].map(n=>`<option ${n===h.paddies?'selected':''}>${n}</option>`).join('')}</select></label><button id="life-qa-unlock">해금 적용</button></div><div class="admin-section"><h3>생산 · 생활 준비</h3><button id="life-qa-supply">씨앗·목재·엽전 지급</button><button id="life-qa-decor">꾸미기 18종 지급</button><button id="life-qa-planted">5작물 성장 중 준비</button><button id="life-qa-grow">심은 작물 즉시 성장</button><label>평판<input id="life-qa-reputation" type="number" min="0" max="100" value="${h.reputation}"></label><button id="life-qa-rep">평판 적용</button></div>${commerce.adminMarkup()}<div class="row"><button id="life-qa-yard">마당으로 이동</button><button id="life-qa-room">집 안으로 이동</button><button id="life-qa-open">생활 관리 열기</button><button id="life-qa-back">기존 관리자 목록</button></div>`,{wide:true});
    commerce.bindAdmin(adminPanel);
    const ready=country=>{api.prepareAncient('4c');if(country)s().ancient.country=country;api.adminJump('ancient-yard-'+s().ancient.country);};
    $('#life-qa-choice').onclick=()=>{api.prepareAncient('choice');Object.assign(home(),freshLife());};
    document.querySelectorAll('[data-life-qa-country]').forEach(b=>b.onclick=()=>{api.prepareAncient('chosen');Object.assign(home(),freshLife());s().ancient.country=b.dataset.lifeQaCountry;commit();api.adminJump(ANCIENT_COUNTRIES[s().ancient.country].village);});
    document.querySelectorAll('[data-life-qa-level]').forEach(b=>b.onclick=()=>{if(!h.owned||!s().ancient.country)ready();setLifeLevel(home(),Number(b.dataset.lifeQaLevel));api.refreshWorld();commit();adminPanel();});
    $('#life-qa-unlock').onclick=()=>{const f=Number($('#life-qa-fields').value),p=Number($('#life-qa-paddies').value),d=HOME_LEVELS[home().level];if(f>d.fields||p>d.paddies){toast('현재 단계의 밭·논 한도를 넘었다.');return;}home().fields=f;home().paddies=p;commit();adminPanel();};
    $('#life-qa-supply').onclick=()=>{if(!h.owned||!s().ancient.country)ready();for(const id of Object.keys(CROPS))home().seeds[id]=Math.min(99999,home().seeds[id]+10);s().inventory.lumber=Math.min(99999,(s().inventory.lumber||0)+12);s().coins=Math.min(1e9,s().coins+1200);commit('시험용 재료를 지급했다.');adminPanel();};
    $('#life-qa-decor').onclick=()=>{for(const id of Object.keys(DECOR))home().decorations[id]=Math.min(99999,home().decorations[id]+1);commit();adminPanel();};
    $('#life-qa-planted').onclick=()=>{ready();setLifeLevel(home(),3);home().paddies=1;let i=0;for(const [id,c]of Object.entries(CROPS)){const plotId=c.kind==='paddy'?'paddy-1':'field-'+(++i),p=home().plots.find(p=>p.id===plotId);p.crop=id;p.plantedAt=Date.now();}commit();adminPanel();};
    $('#life-qa-grow').onclick=()=>{for(const p of home().plots)if(p.crop)p.plantedAt=Date.now()-CROPS[p.crop].minutes*60000;commit();adminPanel();};
    $('#life-qa-rep').onclick=()=>{const n=Number($('#life-qa-reputation').value);if(!Number.isInteger(n)||n<0||n>100)return;home().reputation=n;commit();adminPanel();};
    $('#life-qa-yard').onclick=()=>{if(!h.owned||!s().ancient.country)ready();api.adminJump('ancient-yard-'+s().ancient.country);};$('#life-qa-room').onclick=()=>{if(!h.owned||!s().ancient.country)ready();api.adminJump(ANCIENT_COUNTRIES[s().ancient.country].home);};$('#life-qa-open').onclick=()=>{if(!atHome(s()))ready();open();};$('#life-qa-back').onclick=api.adminPanel;
  }
  function interact(e){if(commerce.interact(e))return true;if(e.type==='homestead'){open(e.id==='life-workbench'?'market':'farm');return true;}if(e.type==='farmPlot'){plot(e.plotId);return true;}return false;}
  return {open,adminPanel,interact,board:commerce.board,cart:commerce.cart};
}
